INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Kunden- und Marktperspektive > Auftragsbearbeitung & Projektmanagement
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Kundenanforderungen bei der Auftragsbearbeitung immer berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Erfüllung ist zentral für Kundenzufriedenheit"}, {"text": "Nein", "correct": false, "because": "Kundenfokus ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Projektmanagement ohne Zeitplanung erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Zeitplanung ist Grundlage für Koordination"}, {"text": "Ja", "correct": false, "because": "Ohne Planung ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Auftragsbearbeitung unabhängig vom Projektmanagement?', 2, '[{"text": "Nein", "correct": true, "because": "Oft miteinander verknüpft"}, {"text": "Ja", "correct": false, "because": "Koordination nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Aufträge ohne Kommunikation mit dem Kunden effektiv bearbeitet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kommunikation sichert Klarheit"}, {"text": "Ja", "correct": false, "because": "Kundenabstimmung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Projektmanagement nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei der Auftragsbearbeitung am wichtigsten?', 3, '[{"text": "Kundenspezifikationen", "correct": true, "because": "Bestimmen Anforderungen"}, {"text": "Lieferantenauswahl", "correct": false, "because": "Sekundär"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das Projektmanagement primär?', 2, '[{"text": "Termingerechte Fertigstellung", "correct": true, "because": "Erfüllt Kundenanforderungen"}, {"text": "Kostensenkung", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Teilziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wird oft im Projektmanagement verwendet?', 2, '[{"text": "Gantt-Diagramm", "correct": true, "because": "Visualisiert Zeitplan"}, {"text": "Farbpalette", "correct": false, "because": "Ästhetisch"}, {"text": "Kostenrechner", "correct": false, "because": "Wirtschaftlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auftragsbearbeitung entscheidend?', 3, '[{"text": "Kommunikation", "correct": true, "because": "Sichert Abstimmung"}, {"text": "Produktgröße", "correct": false, "because": "Physisch"}, {"text": "Lieferantenmarke", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil eines guten Projektmanagements?', 2, '[{"text": "Kundenzufriedenheit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Produktentwicklung", "correct": false, "because": "Teilziel"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Auftragsbearbeitung?', 4, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Erfasst Kundenwünsche"}, {"text": "Planung", "correct": true, "because": "Strukturiert Ablauf"}, {"text": "Umsetzung", "correct": true, "because": "Realisiert Auftrag"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind im Projektmanagement wichtig?', 3, '[{"text": "Zeitplanung", "correct": true, "because": "Koordiniert Ablauf"}, {"text": "Ressourcenmanagement", "correct": true, "because": "Optimiert Einsatz"}, {"text": "Kundenkommunikation", "correct": true, "because": "Sichert Abstimmung"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine effektive Auftragsbearbeitung?', 3, '[{"text": "Kundenzufriedenheit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Effizienz", "correct": true, "because": "Spart Zeit"}, {"text": "Qualitätssicherung", "correct": true, "because": "Erhöht Zuverlässigkeit"}, {"text": "Geringere Anschaffungskosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei schlechtem Projektmanagement auftreten?', 4, '[{"text": "Terminverzögerungen", "correct": true, "because": "Fehlende Planung"}, {"text": "Kostenüberschreitung", "correct": true, "because": "Unkontrollierte Ausgaben"}, {"text": "Kundenunzufriedenheit", "correct": true, "because": "Unerfüllte Erwartungen"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen das Projektmanagement?', 3, '[{"text": "Gantt-Diagramme", "correct": true, "because": "Visualisiert Zeitplan"}, {"text": "Meilensteine", "correct": true, "because": "Markiert Fortschritt"}, {"text": "Risikoanalysen", "correct": true, "because": "Mindert Probleme"}, {"text": "Farbabstimmung", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Kundenanforderungen sind bei der Auftragsbearbeitung zentral. b) Zeitplanung ist im Projektmanagement unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anforderungen ja, Planung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gantt-Diagramme unterstützen das Projektmanagement. b) Auftragsbearbeitung kann ohne Kundenkommunikation erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Diagramme ja, Kommunikation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projektmanagement sichert termingerechte Fertigstellung. b) Auftragsbearbeitung ist unabhängig vom Projektmanagement.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Termine ja, oft verknüpft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kundenzufriedenheit ist ein Vorteil guter Auftragsbearbeitung. b) Projektmanagement ist nur für große Projekte relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zufriedenheit ja, für alle Größen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Meilensteine markieren Fortschritt im Projektmanagement. b) Kommunikation ist bei der Auftragsbearbeitung unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Meilensteine ja, Kommunikation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

